SELECT cc.cc_state, cc.cc_call_center_id, cc.cc_name, SUM(cs.cs_net_profit) AS total_net_profit, SUM(cs.cs_ext_sales_price) AS total_sales, CASE WHEN SUM(cs.cs_net_profit) > 0 THEN 'Profitable' ELSE 'Unprofitable' END AS profit_status, COUNT(DISTINCT p.p_promo_id) AS promo_count, RANK() OVER (PARTITION BY cc.cc_state ORDER BY SUM(cs.cs_net_profit) DESC) AS profit_rank_in_state FROM catalog_sales cs JOIN call_center cc ON cs.cs_call_center_sk = cc.cc_call_center_sk JOIN warehouse w ON cs.cs_warehouse_sk = w.w_warehouse_sk LEFT JOIN promotion p ON cs.cs_promo_sk = p.p_promo_sk GROUP BY cc.cc_state, cc.cc_call_center_id, cc.cc_name HAVING SUM(cs.cs_ext_sales_price) > 10000 ORDER BY cc.cc_state, profit_rank_in_state
